{
  "outcome": "escalate",
  "rationale": "We must escalate this claim because automated findings indicate it is unclear whether an exclusion applies, and the claimant admitted to participating in an impromptu street race. Section 6.2 governs the referral of unclear coverage when material facts are open to more than one interpretation.",
  "citations": [
    {
      "clause_id": "BASIC-6.2",
      "quote": "If the documents submitted do not allow the adjuster to determine whether an exclusion applies, because material facts are disputed, missing or open to more than one reasonable reading, the claim must be escalated for further investigation rather than approved or denied on the information available."
    }
  ]
}
